import React, { useState } from 'react';

const UploadPage = () => {
  const [calendarUploaded, setCalendarUploaded] = useState(false);
  const [files, setFiles] = useState({
    calendar: null,
    baseline: null,
    bfd: null,
    upside: null,
    mostlikely: null,
  });

  const handleFileChange = (type, file) => {
    if (type !== 'calendar' && !calendarUploaded) {
      alert('Please upload Calendar Holiday sheet first.');
      return;
    }

    setFiles((prev) => ({ ...prev, [type]: file }));
    if (type === 'calendar') setCalendarUploaded(true);
  };

  const handleSubmit = () => {
    console.log('Uploaded files:', files);
    alert('Files uploaded successfully!');
  };

  return (
    <div className="upload-page">
      <h2>Upload Revenue Forecast Sheets</h2>
      {['calendar', 'baseline', 'bfd', 'upside', 'mostlikely'].map((type) => (
        <div key={type} style={{ marginBottom: '10px' }}>
          <label>{type.toUpperCase()} Excel:</label>
          <input
            type="file"
            accept=".xlsx, .xls"
            onChange={(e) => handleFileChange(type, e.target.files[0])}
          />
        </div>
      ))}
      <button onClick={handleSubmit}>Submit</button>
    </div>
  );
};

export default UploadPage;
